'use strict';
const AiMaking=(()=>{
 const P=ProductionClient,T=ProductionTimeline,client=new P.Client();
 const state={owner:null,project:null,projects:[],assets:[],cards:[],selected:0,checked:new Set(),input:'',sourceSegments:null,inputDirty:false,mode:'sentence',busy:false,loading:false,message:'',run:null,job:null,filter:'all',edited:{},styleId:null,token:0,legacy:false,epoch:0,position:0,previewMode:'source'};
 const refKey=()=>`ai-production-project:${S.p?.id||'standalone'}`;
 const current=()=>state.cards[state.selected];
 const asset=(id,revision)=>state.assets.find(item=>item.id===id&&(revision===undefined||item.revision===revision));
 const source=()=>asset(state.project?.source?.asset_id,state.project?.source?.revision);
 const scope=()=>({owner:state.owner,id:state.project?.id,epoch:state.epoch});
 const live=(mark,project=true)=>mark.owner===(S.p?.id||'standalone')&&mark.owner===state.owner&&mark.epoch===state.epoch&&(!project||mark.id===state.project?.id);
 const styles=()=>state.assets.filter(item=>item.kind==='style'&&item.metadata?.technical_status==='passed');
 const style=card=>asset(card?.style?.asset_id,card?.style?.revision);
 const time=value=>Number.isFinite(Number(value))?clock(value):'时间待定';
 const detail=value=>typeof value==='string'?value:JSON.stringify(value,null,2);
 const selectedIds=()=>P.selection(state.project,state.checked);
 const shown=()=>state.cards.filter(card=>state.filter==='all'||card.status===state.filter||card.decision===state.filter);
 const requestProject=async()=>{const mark=scope();if(mark.id){const result=await client.request(`/projects/${mark.id}`);if(live(mark))applyProject(result.project);}};
 function remember(){if(state.project)writeSetting(`ai-production-project:${state.owner}`,state.project.id);}
 function applyProject(project,{input=false}={}){if(state.project?.id===project?.id&&state.project.revision>project.revision)return;state.project=project;state.projects=state.projects.map(p=>p.id===project.id?project:p);state.cards=project?.cards||[];state.checked=new Set(P.selection(project,state.checked));state.selected=Math.max(0,Math.min(state.selected,state.cards.length-1));if(input&&!state.inputDirty){state.sourceSegments=project?.segments||[];state.input=state.sourceSegments.map(item=>item.text).join('\n');}remember();}
 function fail(error){state.message=error.message||String(error);setStatus(state.message);toast(state.message);}
 function setStatus(message){state.message=message;const el=$('#ai-status');if(el)el.textContent=message;}
 function setBusy(value){state.busy=value;$$('[data-ai-action="preview-current"]').forEach(button=>button.disabled=value||P.pending(state.job?.status)||current()?.decision!=='broll');const picker=$('#ai-production-project');if(picker)picker.disabled=value;$$('[data-ai-action="video"],[data-ai-action="audio"]').forEach(button=>button.disabled=value);const generateButton=$('[data-ai-action="generate"]');if(generateButton)generateButton.disabled=value||P.pending(state.run?.status);const renderButton=$('[data-ai-action="render"]');if(renderButton)renderButton.disabled=value||!state.project?.source||P.pending(state.job?.status);if($('#ai-batch-controls'))$('#ai-batch-controls').innerHTML=controlsHTML();}
 function mediaCard(card,index){const selected=index===state.selected,chosen=style(card),preview=P.media(card.preview_url),poster=P.media(card.poster_url)||P.blob(chosen?.metadata?.poster_hash);
  const visual=preview?`<video controls playsinline preload="none" ${poster?`poster="${esc(poster)}"`:''} src="${esc(preview)}" aria-label="实际替换预览"></video><span class="ai-visual-tag">${card.render_report?.review_context?'口播原画幅 · 原声音预览':'实际制作预览'}</span>`:card.decision==='broll'&&poster?`<img class="ai-style-poster" src="${poster}" alt="${esc(chosen?.name||'样式')}参考"><span class="ai-visual-tag">样式参考 · 当前内容待预览</span>`:`<div class="ai-aroll-placeholder">${icon(card.decision==='gap'?'scan':'film')}<strong>${card.decision==='keep'?'保留口播画面':card.decision==='gap'?'等待合适素材':'待生成实际预览'}</strong><span>${card.decision==='keep'?'本段不覆盖 B-roll':card.decision==='gap'?'查看缺口与下一步':'替换后将实际渲染'}</span></div>`;
  return `<article class="ai-line-card ${selected?'selected':''} ${state.checked.has(card.id)?'batch-selected':''}" data-ai-card="${index}"><div class="ai-card-top"><label class="ai-check-label"><input type="checkbox" data-ai-check="${esc(card.id)}" ${state.checked.has(card.id)?'checked':''} aria-label="选择第${index+1}张"><span class="ai-line-number">${String(index+1).padStart(2,'0')}</span></label><span class="ai-match-state">${esc(P.label(card.status))} · ${esc(P.label(card.decision))}</span><span class="spacer"></span><span class="ai-time">${time(card.start)} — ${time(card.end)}</span></div><div class="ai-visual">${visual}</div><div class="ai-spoken"><span>口播片段 ${String(index+1).padStart(2,'0')}</span><p>${esc(card.text)}</p></div><div class="ai-production-reason">${esc(card.reason||'暂无判断依据')}</div>${card.render_report?.layout?.status==='needs_revision'?`<div class="ai-layout-warning"><strong>版式需修改 · 暂不能确认</strong>${(card.render_report.layout.issues||[]).map(issue=>`<p>${esc(issue.message||detail(issue))}</p>`).join('')}</div>`:''}${card.missing?.length?`<div class="ai-missing">待补充：${card.missing.map(item=>esc(detail(item))).join('；')}</div>`:''}<details class="ai-evidence"><summary>依据与候选 · ${(card.evidence||[]).length} / ${(card.alternatives||[]).length}</summary>${(card.evidence||[]).map(item=>`<pre>${esc(detail(item))}</pre>`).join('')}${(card.alternatives||[]).map(item=>`<pre>${esc(detail(item))}</pre>`).join('')}${card.render_report?`<p>渲染检查</p><pre>${esc(detail(card.render_report))}</pre>`:''}</details><div class="ai-card-foot"><span>${esc(chosen?.name||'保留原口播')}${card.style?` · v${card.style.revision}`:''}</span><button data-ai-action="select" data-ai-index="${index}">${selected?'正在编辑':'选择视觉'}${icon('arrow')}</button></div></article>`;
 }
 function timingEditor(card){
  if(!T.active(card))return '<p class="ai-help">原口播时间保持不变。选择并保存 B-roll 样式后，可调整它的覆盖时间与转场。</p>';
  return `<div class="ai-edit"><h3>覆盖时间与剪辑</h3><div class="ai-time-fields"><label>开始（秒）<input id="ai-cut-start" type="number" min="0" step="0.01" value="${Number(card.start)}"></label><label>结束（秒）<input id="ai-cut-end" type="number" min="0" step="0.01" value="${Number(card.end)}"></label></div><button class="button" data-ai-action="save-time">保存覆盖时间</button><label>画幅适配<select id="ai-crop"><option value="contain" ${card.crop_mode!=='cover'?'selected':''}>完整显示画面</option><option value="cover" ${card.crop_mode==='cover'?'selected':''}>铺满原口播画幅</option></select></label><label>转场<select id="ai-transition"><option value="cut" ${card.transition!=='dissolve'?'selected':''}>直接切换</option><option value="dissolve" ${card.transition==='dissolve'?'selected':''}>淡入淡出</option></select></label><button class="button" data-ai-action="save-effect">保存画幅与转场</button><small>修改后需重新预览、确认。</small></div>`;
 }
 function cutHTML(){
  if(!state.project)return '';
  const card=current(),total=T.duration(state.project,source()),original=P.blob(source()?.blob_hash);
  const preview=state.previewMode==='card'&&card?.decision==='broll'?P.media(card.preview_url):'';
  const media=preview||original,position=preview?0:Math.min(state.position,total);
  const labels=Array.from({length:5},(_,i)=>`<span>${time(total*i/4)}</span>`).join('');
  const bars=state.cards.map((item,index)=>{
   const left=Math.max(0,Number(item.start)||0)/total*100,width=Math.max(0,Math.min(total,item.end)-item.start)/total*100;
   return `<button class="ai-time-clip ${item.decision} ${item.status==='rejected'?'rejected':''} ${index===state.selected?'selected':''}" style="left:${left}%;width:${width}%" data-ai-action="select" data-ai-index="${index}" data-cut-index="${index}" aria-label="定位第${index+1}段：${esc(item.text)}" title="${esc(item.text)} · ${time(item.start)} — ${time(item.end)}">${T.active(item)?'<span class="ai-trim start" data-cut-part="start" aria-hidden="true"></span>':''}<span class="ai-clip-text">${index+1} · ${item.decision==='broll'?'B-roll':item.decision==='gap'?'待补':'口播'}</span>${T.active(item)?'<span class="ai-trim end" data-cut-part="end" aria-hidden="true"></span>':''}</button>`;
  }).join('');
  return `<section class="ai-cut" aria-label="口播与制作时间线"><div class="ai-source-view"><div class="ai-source-head"><strong>${preview?'本段实际制作预览':'口播原片'}</strong><select id="ai-preview-mode" aria-label="选择预览内容"><option value="source" ${state.previewMode==='source'?'selected':''}>口播原片</option><option value="card" ${state.previewMode==='card'?'selected':''}>当前片段制作预览</option></select></div>${media?`<video id="ai-cut-video" controls playsinline preload="metadata" src="${esc(media)}" data-cut-offset="${preview?Number(card.start):0}" data-cut-position="${position}" aria-label="${preview?'当前片段实际预览':'口播原片预览'}"></video>`:'<p class="ai-help">原片版本暂不可用，草稿仍保留。请读取保存草稿后重试。</p>'}${state.previewMode==='card'&&!preview?'<p class="ai-help">此段还没有实际制作预览，当前显示原片。</p>':''}</div><div class="ai-sequence"><div class="ai-section-head"><div><span class="ai-step">制作时间线</span><h2>${esc(state.project.name)}</h2></div><span>${state.cards.length} 段 · ${time(total)}</span></div><p class="ai-cut-caption">${esc(card?.text||'选择一个片段查看判断与素材。')}</p><div class="ai-time-ruler">${labels}</div><div class="ai-time-lane" id="ai-time-lane">${bars}<i id="ai-playhead" class="ai-playhead" style="left:${Math.min(state.position,total)/total*100}%" aria-hidden="true"></i></div><label class="ai-seek-label" for="ai-time-seek">原片定位 <output id="ai-position">${time(state.position)}</output></label><input id="ai-time-seek" type="range" min="0" max="${total}" step="${1/T.fps(source())}" value="${Math.min(state.position,total)}" aria-label="原片时间定位"><div class="ai-editor-actions"><button class="button" data-ai-action="frame-back">上一帧</button><button class="button" data-ai-action="frame-forward">下一帧</button><button class="button" data-ai-action="preview-current" ${card?.decision==='broll'&&!state.busy&&!P.pending(state.job?.status)?'':'disabled'}>生成本段预览</button></div><p class="ai-help">点击定位；拖动 B-roll 移动覆盖范围，拖动两端调整时长。精确时间与转场可在下方编辑。</p><p class="ai-help" id="ai-drag-status" role="status"></p></div></section>`;
 }
 function selectCard(index){
  if(state.busy)return;
  if(editorDirty())throw new Error('当前替换尚未保存，请先保存后再切换片段。');
  const card=state.cards[index];if(!card)return;
  state.selected=index;state.position=Number(card.start)||0;state.edited={};state.styleId=null;redraw();
 }
 function seek(value){
  state.position=Math.max(0,Math.min(T.duration(state.project,source()),value));
  const video=$('#ai-cut-video'),offset=Number(video?.dataset?.cutOffset)||0;
  if(video&&Number.isFinite(video.duration))video.currentTime=Math.max(0,Math.min(video.duration,state.position-offset));
  positionUI();
 }
 function positionUI(){
  const slider=$('#ai-time-seek'),head=$('#ai-playhead'),label=$('#ai-position');
  if(slider)slider.value=state.position;if(label)label.textContent=time(state.position);
  if(head?.style)head.style.left=`${state.position/T.duration(state.project,source())*100}%`;
 }
 function bindCut(){
  const video=$('#ai-cut-video');if(!video?.addEventListener)return;
  video.addEventListener('loadedmetadata',()=>{video.currentTime=Math.min(Number(video.dataset.cutPosition)||0,video.duration);});
  video.addEventListener('timeupdate',()=>{state.position=video.currentTime+(Number(video.dataset.cutOffset)||0);positionUI();});
  const lane=$('#ai-time-lane');if(!lane)return;
  lane.addEventListener('pointerdown',event=>{
   const button=event.target.closest('[data-cut-index]'),card=state.cards[Number(button?.dataset.cutIndex)];
   if(!button||!T.active(card)||state.busy||event.button!==0)return;
   if(editorDirty()){fail(new Error('请先保存当前替换，再调整时间。'));return;}
   const mark=scope(),startX=event.clientX,width=lane.getBoundingClientRect().width,total=T.duration(state.project,source());
   const part=event.target.dataset.cutPart||'move';let moved=false,next;
   button.setPointerCapture(event.pointerId);
   const move=e=>{if(Math.abs(e.clientX-startX)<3&&!moved)return;moved=true;next=T.drag(card,part,(e.clientX-startX)/width*total,total);button.style.left=`${next.start/total*100}%`;button.style.width=`${(next.end-next.start)/total*100}%`;$('#ai-drag-status').textContent=`${time(next.start)} — ${time(next.end)}，松开保存`;};
   const finish=e=>{button.removeEventListener('pointermove',move);button.removeEventListener('pointerup',finish);button.removeEventListener('pointercancel',cancel);if(moved){button.addEventListener('click',ev=>{ev.preventDefault();ev.stopPropagation();},{once:true});if(live(mark))Promise.resolve().then(()=>batch('retime',[card.id],T.timing(state.project,source(),card,next.start,next.end))).catch(error=>{redraw();fail(error);});}};
   const cancel=()=>{button.removeEventListener('pointermove',move);button.removeEventListener('pointerup',finish);button.removeEventListener('pointercancel',cancel);redraw();};
   button.addEventListener('pointermove',move);button.addEventListener('pointerup',finish);button.addEventListener('pointercancel',cancel);
  });
 }
 function editorDirty(){return !!state.styleId||Object.keys(state.edited).length>0;}
 function requireSaved(){if(editorDirty())throw new Error('替换尚未保存，请先保存当前替换，再预览或确认。');}
 async function saveTiming(){requireSaved();const card=current();if(card)await batch('retime',[card.id],T.timing(state.project,source(),card,$('#ai-cut-start').value,$('#ai-cut-end').value));}
 async function saveEffect(){requireSaved();const card=current();if(card)await batch('effect',[card.id],{crop_mode:$('#ai-crop').value,transition:$('#ai-transition').value});}
 function editorHTML(){const card=current(),chosen=asset(state.styleId)||style(card);if(!card)return `<div class="ai-inspector-empty">${icon('grid')}<strong>选中一段口播</strong><p>读取字幕或输入文稿后，让 Agent 提出有依据的画面草稿。</p><button class="button" data-ai-action="cases">导入已有复刻样式</button></div>`;
  const fields=P.fields(chosen).map(field=>{const value=Object.hasOwn(state.edited,field.key)?state.edited[field.key]:card.fields?.[field.key]??'';if(field.type==='image'){return `<div class="ai-image-field"><span>${esc(field.label||field.key)}</span><select data-ai-field="${esc(field.key)}" data-ai-type="image"><option value="">沿用现有图片</option>${state.assets.filter(item=>item.kind==='image').map(item=>`<option value="${esc(JSON.stringify({asset_id:item.id,revision:item.revision}))}" ${value?.asset_id===item.id&&value?.revision===item.revision?'selected':''}>${esc(item.name)} · v${item.revision}</option>`).join('')}</select>${value?.asset_id&&asset(value.asset_id,value.revision)?`<img src="${P.blob(asset(value.asset_id,value.revision).blob_hash)}" alt="已选图片">`:''}<small>图片固定到共享资产版本</small></div>`;}return `<label>${esc(field.label||field.key)}<input data-ai-field="${esc(field.key)}" data-ai-type="${esc(field.type||'text')}" value="${esc(value)}" ${field.max_length?`maxlength="${Number(field.max_length)}"`:''} placeholder="${field.max_length?`最多${field.max_length}字`:'填写替换内容'}"></label>`;}).join('');
  return `<div class="ai-inspector-head"><span>当前片段 ${String(state.selected+1).padStart(2,'0')}</span><strong>${esc(card.text)}</strong><small>${esc(card.reason)}</small></div>${card.style&&!style(card)?'<p class="ai-help">此片段固定的历史样式版本暂未载入。已有预览仍可审看；切换样式会使用明确显示的新版本。</p>':''}<div class="ai-choices"><h3>为这个片段选择画面</h3><button class="ai-choice ai-aroll-choice ${card.decision==='keep'?'active':''}" data-ai-choice="none"><span>${icon('film')}</span><strong>保留口播</strong><small>舍弃 B-roll，保留原画面</small></button>${styles().map(item=>`<button class="ai-choice ${chosen?.id===item.id?'active':''}" data-ai-choice="${esc(item.id)}"><img src="${P.blob(item.metadata.poster_hash)}" alt=""><span><strong>${esc(item.name)}</strong><small>${esc(item.metadata.purpose||'共享样式')} · v${item.revision}</small></span></button>`).join('')}</div>${timingEditor(card)}<div class="ai-edit"><h3>可替换元素</h3>${fields||'<p class="ai-help">先选择样式，或保留口播。</p>'}<div class="ai-editor-actions"><button class="button" data-ai-action="images">批量导入图片</button><button class="button" data-ai-action="cases">导入复刻样式</button></div><button class="button" data-ai-action="save-fields">保存当前替换</button><button class="button" data-ai-action="discard-edits">撤销未保存替换</button><button class="button" data-ai-action="save-batch" ${selectedIds().length?'':'disabled'}>将改动应用到所选 ${selectedIds().length} 张</button><div class="ai-editor-actions"><button class="button" data-ai-action="preview-current">预览当前</button><button class="button primary" data-ai-action="confirm">${card.status==='approved'?'重置确认':'确认这张画面'}</button></div><p class="ai-help">替换实际写入渲染参数。先生成并审看当前预览，再确认；修改会撤销旧确认。</p></div>`;
 }
 function controlsHTML(){const count=selectedIds().length;return `<div class="ai-production-controls"><label><input id="ai-select-all" type="checkbox" ${shown().length&&shown().every(card=>state.checked.has(card.id))?'checked':''}>全选当前</label><select id="ai-review-filter" aria-label="筛选草稿">${[['all','全部'],['draft','待确认'],['broll','建议画面'],['keep','保留口播'],['gap','待补素材'],['approved','已确认'],['rejected','已舍弃']].map(([key,label])=>`<option value="${key}" ${state.filter===key?'selected':''}>${label}</option>`).join('')}</select><span>已选 ${count}</span><button class="button" data-ai-action="preview" ${count&&!state.busy&&!P.pending(state.job?.status)?'':'disabled'}>预览</button><button class="button" data-ai-action="approve" ${count&&!state.busy?'':'disabled'}>确认</button><button class="button" data-ai-action="reject" ${count&&!state.busy?'':'disabled'}>舍弃</button><button class="button" data-ai-action="reset" ${count&&!state.busy?'':'disabled'}>重置</button></div>`;}
 function runHTML(){const run=state.run;if(!run)return '';const events=run.events||[];return `<details class="ai-agent-events" ${P.pending(run.status)||run.error?'open':''}><summary>Agent · ${esc(P.label(run.status))} · ${events.length} 步${events.at(-1)?.message?' · '+esc(events.at(-1).message):''}</summary>${run.error?`<p class="ai-error">${esc(run.error)}</p>`:''}<ol>${events.map(event=>`<li><strong>${esc(event.message||event.type)}</strong><small>${esc(event.type)}</small>${event.data&&Object.keys(event.data).length?`<details><summary>查看证据与工具结果</summary><pre>${esc(detail(event.data))}</pre></details>`:''}</li>`).join('')}</ol>${P.pending(run.status)?'<button class="button" data-ai-action="cancel-run">停止本次执行</button>':['failed','interrupted','error'].includes(run.status)?'<button class="button" data-ai-action="resume-run">从保存进度继续</button>':''}</details>`;}
 function deliveryHTML(){const job=state.job,delivery=T.delivery(state.project),url=P.media(delivery?.url);return `${job?`<p class="ai-job-status">${job.kind==='render'?'成片':'预览'} · ${esc(P.label(job.status))}${job.error?'：'+esc(job.error):''}</p>`:''}${!url&&state.project?.deliveries?.length?'<p class="ai-job-status">已有成片对应旧版内容，请按当前确认重新生成。</p>':''}${url?`<details class="ai-delivery"><summary>实际审阅成片 · 项目 v${delivery.project_revision}</summary><video controls playsinline preload="none" src="${esc(url)}"></video><a class="button" href="${esc(url)}" download>下载审阅成片</a><pre>${esc(detail(delivery.report||{}))}</pre></details>`:''}`;}
 function paint(){if(S.view!=='ai-making')return;$('#content').innerHTML=`<div class="ai-making"><details class="ai-input" ${!state.cards.length||P.pending(state.run?.status)||state.run?.error?'open':''}><summary class="ai-input-summary">${esc(state.project?.name||'准备口播内容')}<span>文稿、导入与 Agent 执行记录</span></summary><div class="ai-input-top"><span class="ai-step">01 / 输入内容</span><span>${state.project?'已保存制作草稿 · v'+state.project.revision:state.loading?'正在读取已保存草稿…':'原视频与制作草稿独立保存'}</span></div><div class="ai-input-grid"><div class="ai-script"><label for="ai-script-input">文稿内容</label><textarea id="ai-script-input" placeholder="粘贴一段口播文稿，或读取当前视频字幕。">${esc(state.input)}</textarea></div><div class="ai-import"><strong>上传你的素材</strong><p>上传视频读取真实口播；也可以上传语音，或继续当前视频已有的制作草稿。</p><input id="ai-video-file" type="file" accept="video/*,.mp4,.mov,.mkv,.webm,.avi" hidden><button class="button ai-video-upload" data-ai-action="video" ${state.busy?'disabled':''}>${icon('film')}上传视频并生成分镜</button><input id="ai-audio-file" type="file" accept="audio/*,.mp3,.wav,.m4a,.aac,.flac,.ogg" hidden><button class="button" data-ai-action="audio" ${state.busy?'disabled':''}>${icon('audio')}上传语音并转写</button><button class="button" data-ai-action="transcript" ${!S.p||state.busy?'disabled':''}>${icon('captions')}使用当前视频字幕</button><small>${S.p?'当前视频：'+esc(titleOf(S.p)):'还没有选择视频'}</small></div></div><div class="ai-input-bottom"><div class="ai-segment-control"><span>Agent 按叙事判断，允许保留口播</span></div><span class="spacer"></span>${state.project?'<button class="button" data-ai-action="duplicate">另建制作副本</button>':''}<button class="button" data-ai-action="refresh" ${state.busy?'disabled':''}>读取保存草稿</button><button class="button primary" data-ai-action="generate" ${state.busy||P.pending(state.run?.status)?'disabled':''}>${icon('scan')}${P.pending(state.run?.status)?'Agent 正在制作…':'生成分镜建议'}</button></div>${state.legacy?'<p class="ai-legacy-note">旧浏览器草稿仍保留；当前 Agent 草稿保存到服务器。</p>':''}${state.projects.length&&state.project?`<label class="ai-production-switch">制作草稿<select id="ai-production-project" ${state.busy?'disabled':''}>${(state.owner==='standalone'?state.projects:P.matchingProjects(state.owner,state.projects,state.assets)).map(project=>`<option value="${esc(project.id)}" ${state.project.id===project.id?'selected':''}>${esc(project.name)} · ${project.cards?.length||0} 个判断</option>`).join('')}</select></label>`:''}<div id="ai-agent-panel">${runHTML()}</div></details><p class="ai-input-status" id="ai-status" role="status">${esc(state.message||'Agent 会查看口播与原片、检索共享样式和图片、比较候选，再执行和检查。')}</p><div id="ai-cut-panel">${cutHTML()}</div><div class="ai-work"><section class="ai-board"><div class="ai-section-head"><div><span class="ai-step">02 / 分镜卡</span><h2>有依据的画面草稿</h2></div><div class="ai-output-actions"><button class="button" data-ai-action="render" ${state.project?.source&&!state.busy?'':'disabled'}>生成审阅成片</button><button class="button" data-ai-action="export" ${state.project?'':'disabled'}>${icon('download')}导出方案</button></div></div><div id="ai-batch-controls">${controlsHTML()}</div><div id="ai-delivery-panel">${deliveryHTML()}</div><div class="ai-card-list">${state.cards.length?shown().map(card=>mediaCard(card,state.cards.indexOf(card))).join(''):`<div class="ai-board-empty">${icon('layers')}<strong>${state.loading?'正在读取真实草稿…':'分镜会出现在这里'}</strong><p>先读取字幕或输入文稿。Agent 会保存选择、理由、候选和待补素材。</p></div>`}</div></section><aside class="ai-inspector"><div class="ai-section-head"><div><span class="ai-step">03 / 选择与替换</span><h2>视觉预设库</h2></div><span>${styles().length} 个可执行样式</span></div><div class="ai-inspector-scroll">${editorHTML()}</div></aside></div><input id="ai-shared-images" type="file" accept="image/png,image/jpeg,image/webp" multiple hidden></div>`;bindCut();}
 function redraw(){if(S.view!=='ai-making')return;const cut=$('#ai-cut-panel');if(cut){cut.innerHTML=cutHTML();bindCut();}const board=$('.ai-card-list'),inspector=$('.ai-inspector-scroll');if(!board||!inspector)return;board.innerHTML=shown().map(card=>mediaCard(card,state.cards.indexOf(card))).join('');inspector.innerHTML=editorHTML();$('#ai-batch-controls').innerHTML=controlsHTML();$('#ai-delivery-panel').innerHTML=deliveryHTML();}
 async function hydrate(force=false){const owner=S.p?.id||'standalone';if(state.loading&&!force)return;const token=++state.token;state.loading=true;try{const data=await client.library();if(token!==state.token||owner!==(S.p?.id||'standalone'))return;state.assets=data.assets;state.projects=data.projects;const selected=P.chooseProject(owner==='standalone'?null:owner,data.projects,data.assets,readSetting(refKey(),null));if(selected){applyProject(selected,{input:true});const last=selected.runs?.at(-1),id=typeof last==='string'?last:last?.id;if(id){const result=await client.request(`/runs/${id}`);if(token!==state.token)return;state.run=result.run;if(P.pending(state.run.status))pollRun(id,selected.id);}}else if(!state.inputDirty){state.project=null;state.cards=[];state.sourceSegments=S.p?.transcript?.segments||null;state.input=state.sourceSegments?.map(item=>item.text).join('\n')||readSetting(`ai-production-input:${owner}`,'');}state.message=selected?'已读取后端保存的制作草稿，可继续审看。':'可直接使用当前视频字幕，或输入本期口播文稿。';}catch(error){if(token===state.token)fail(error);}finally{if(token===state.token){state.loading=false;paint();}}}
 function render(){const owner=S.p?.id||'standalone';if(state.owner!==owner){state.epoch++;state.token++;state.busy=false;state.position=0;state.previewMode='source';state.owner=owner;state.legacy=!!readSetting(`ai-making:${owner}`,null)?.cards?.length;state.project=null;state.cards=[];state.checked.clear();state.selected=0;state.input='';state.inputDirty=false;state.edited={};state.styleId=null;state.run=null;state.job=null;state.loading=false;state.message='';paint();hydrate();}else{paint();if(!state.loading&&!state.project)hydrate();}}
 async function ensureProject(){const mark=scope();if(state.project&&!state.inputDirty)return state.project;if(!state.input.trim())throw new Error('请先输入文稿、上传语音或读取视频字幕。');let result;if(S.p&&state.sourceSegments&&state.input===state.sourceSegments.map(item=>item.text).join('\n')&&state.sourceSegments===S.p.transcript?.segments){result=await client.request('/workbench-import',{project_id:S.p.id});}else{const sourceAsset=state.assets.find(item=>item.kind==='source'&&item.metadata?.provenance?.workbench_id===S.p?.id);const payload={name:S.p?titleOf(S.p).replace(/\.[^.]+$/,'')+' · 制作':'文稿制作',...(sourceAsset?{source_id:sourceAsset.id}:{}),...(state.sourceSegments&&state.input===state.sourceSegments.map(item=>item.text).join('\n')?{segments:state.sourceSegments}:{transcript:state.input})};result=await client.request('/projects',payload);}if(!live(mark))return null;state.inputDirty=false;applyProject(result.project);return result.project;}
 async function generate(resume=null){if(state.busy||P.pending(state.run?.status))return;requireSaved();const entering=scope();setBusy(true);try{const project=await ensureProject();if(!live(entering,false)||!project)return;const mark=scope(),result=await client.request(`/projects/${project.id}/run`,resume?{resume_run_id:resume}:{});if(!live(mark))return;state.run=result.run;setStatus('Agent 正在查找证据、比较样式与制作草稿…');paint();pollRun(result.run.id,project.id,mark);}catch(error){if(live(entering,false))fail(error);}finally{if(live(entering,false))setBusy(false);}}
 async function pollRun(id,projectId,mark=scope()){try{const result=await client.request(`/runs/${id}`);if(!live(mark)||state.project?.id!==projectId)return;state.run=result.run;if($('#ai-agent-panel'))$('#ai-agent-panel').innerHTML=runHTML();if(P.pending(result.run.status)){setTimeout(()=>pollRun(id,projectId,mark),1400);return;}await requestProject();if(!live(mark))return;paint();setStatus(result.run.error||'Agent 草稿已保存，可以批量选择、修改和审看。');}catch(error){if(!live(mark))return;state.run={...state.run,status:'error',error:error.message};fail(error);if($('#ai-agent-panel'))$('#ai-agent-panel').innerHTML=runHTML();}}
 async function batch(action,ids=selectedIds(),extra={}){if(state.busy)return false;if(action!=='replace')requireSaved();const mark=scope();setBusy(true);try{const result=await client.request(`/projects/${mark.id}/batch`,P.batchBody(state.project,ids,action,extra));if(!live(mark))return false;applyProject(result.project);state.edited={};state.styleId=null;redraw();setStatus('改动已保存到制作项目。');return true;}catch(error){if(live(mark))throw error;return false;}finally{if(live(mark))setBusy(false);}}
 async function saveFields(all=false){const card=current();if(!card)return;const extra={fields:{...state.edited}};if(state.styleId&&(state.styleId!==card.style?.asset_id||asset(state.styleId)?.revision!==card.style?.revision))extra.style_id=state.styleId;if(!Object.keys(extra.fields).length&&!extra.style_id)throw new Error('请先修改字段或选择其他样式。');if(await batch('replace',all?selectedIds():[card.id],extra))setStatus('替换已保存，旧确认与预览已失效。请重新预览。');}
 async function startJob(kind,ids=selectedIds()){if(state.busy||P.pending(state.job?.status))return;requireSaved();if(!state.project)throw new Error('请先生成并保存制作草稿。');if(kind==='preview'){ids=P.selection(state.project,ids).filter(id=>state.cards.some(card=>card.id===id&&card.decision==='broll'));if(!ids.length)throw new Error('请选择有样式的 B-roll 卡片。保留口播不需要额外渲染。');}const mark=scope();setBusy(true);try{const result=await client.request(`/projects/${mark.id}/${kind}`,kind==='preview'?{card_ids:ids}:{});if(!live(mark))return;state.job={...result.job,kind};paint();pollJob(result.job.id,mark.id,kind,mark);}catch(error){if(live(mark))throw error;}finally{if(live(mark))setBusy(false);}}
 async function pollJob(id,projectId,kind,mark=scope()){try{const result=await client.request(`/jobs/${id}`);if(!live(mark)||state.project?.id!==projectId)return;state.job={...result.job,kind};if($('#ai-delivery-panel'))$('#ai-delivery-panel').innerHTML=deliveryHTML();if(P.pending(result.job.status)){setTimeout(()=>pollJob(id,projectId,kind,mark),1400);return;}await requestProject();if(!live(mark))return;redraw();setBusy(false);setStatus(result.job.error||'实际输出与检查结果已保存。');}catch(error){if(!live(mark))return;state.job={...state.job,status:'failed',error:error.message};fail(error);}}
 function useTranscript(){if(!S.p?.transcript?.segments?.length){toast('当前视频还没有字幕。请先到“拉片”中转文字。');return;}state.sourceSegments=S.p.transcript.segments;state.input=state.sourceSegments.map(item=>item.text).join('\n');state.inputDirty=!state.project||state.input!==state.project.segments.map(item=>item.text).join('\n');$('#ai-script-input').value=state.input;setStatus(`已读取 ${state.sourceSegments.length} 段真实字幕，点击生成分镜建议。`);}
 function sendVideo(file){return new Promise((resolve,reject)=>{const request=new XMLHttpRequest();request.open('POST',`/api/projects?name=${encodeURIComponent(file.name)}`);request.setRequestHeader('Content-Type','application/octet-stream');request.timeout=4*60*60*1000;request.upload.onprogress=event=>{if(event.lengthComputable)setStatus(`正在上传视频 ${Math.round(event.loaded/event.total*100)}%…`);};request.onload=()=>{let result;try{result=JSON.parse(request.responseText);}catch{return reject(new Error('视频导入响应无法读取。'));}request.status>=200&&request.status<300?resolve(result):reject(new Error(result.error||'视频上传失败。'));};request.onerror=()=>reject(new Error('本机连接中断，请重新上传。'));request.ontimeout=()=>reject(new Error('视频上传超时。'));request.send(file);});}
 async function uploadVideo(file){if(!file||state.busy)return;setBusy(true);try{const imported=await sendVideo(file);await selectProject(imported.id,{autoplay:false,stayView:true});await hydrate(true);if(!S.p?.has_audio)throw new Error('视频已导入，但没有音轨。请填写文稿后生成草稿。');await api(url(imported.id,'/transcribe'),{});while(S.view==='ai-making'&&S.p?.id===imported.id){const project=await api(url(imported.id));upsert(project);S.p=project;if(project.transcript?.status==='ready'){useTranscript();setBusy(false);await generate();return;}if(project.transcript?.status==='error')throw new Error(project.transcript.message);setStatus(project.transcript?.message||'正在本地识别口播…');await new Promise(resolve=>setTimeout(resolve,1000));}}catch(error){fail(error);}finally{setBusy(false);}}
 async function transcribe(file){if(!file||state.busy)return;if(file.size>60*1024*1024)throw new Error('语音文件请控制在60 MB以内。');setBusy(true);try{setStatus('正在本地识别语音…');const response=await fetch('/api/ai-making/transcribe',{method:'POST',headers:{'Content-Type':file.type||'application/octet-stream'},body:file});const result=await response.json();if(!response.ok)throw new Error(result.error||'语音识别失败。');if(!result.segments?.length)throw new Error('没有识别到说话内容。');state.sourceSegments=result.segments;state.input=result.segments.map(item=>item.text).join('\n');state.inputDirty=true;$('#ai-script-input').value=state.input;setBusy(false);await generate();}finally{setBusy(false);}}
 async function uploadImages(files){if(!files?.length||state.busy)return;setBusy(true);let done=0;const errors=[];try{for(const file of files){setStatus(`正在导入 ${file.name}…`);try{await client.upload(file);done++;}catch(error){errors.push(`${file.name}：${error.message}`);}}state.assets=(await client.request('/assets')).assets||[];redraw();setStatus(`${done}/${files.length} 张图片已存入共享库。${errors.join('；')}`);}finally{setBusy(false);if($('#ai-shared-images'))$('#ai-shared-images').value='';}}
 async function importCases(){const result=await client.request('/cases');const cases=result.cases||[];showModal('导入已有复刻样式',`<p>重新渲染和替换验证通过后，样式将进入共享库。</p><div class="stack">${cases.map(item=>`<button class="button" data-ai-action="import-case" data-ai-case="${esc(item.case_id||item.id)}">${esc(item.name)}</button>`).join('')}</div>`,button('关闭','close-dialog'));}
 async function importCase(id){if(state.busy)return;setBusy(true);try{setStatus('正在执行真实案例渲染与替换验证…');await client.request('/cases/import',{case_id:id});state.assets=(await client.request('/assets')).assets||[];closeModal();paint();setStatus('真实复刻样式已写入共享库。');}finally{setBusy(false);}}
 function exportPlan(){if(!state.project)return;const link=document.createElement('a');link.href=`${P.prefix}/projects/${state.project.id}/export`;link.download='AI制作-分镜方案.json';link.click();}
 document.addEventListener('input',event=>{if(S.view!=='ai-making')return;const target=event.target;if(target.id==='ai-time-seek'){seek(Number(target.value));return;}if(target.id==='ai-script-input'){state.input=target.value;state.inputDirty=true;state.sourceSegments=null;writeSetting(`ai-production-input:${state.owner}`,state.input);}else if(target.dataset.aiField){state.edited[target.dataset.aiField]=target.dataset.aiType==='number'?Number(target.value):target.value;}});
 document.addEventListener('change',event=>{if(S.view!=='ai-making')return;const target=event.target;let task;if(target.id==='ai-preview-mode'){state.previewMode=target.value;$('#ai-cut-panel').innerHTML=cutHTML();bindCut();return;}if(target.id==='ai-video-file')task=uploadVideo(target.files?.[0]);if(target.id==='ai-audio-file')task=transcribe(target.files?.[0]);if(target.id==='ai-shared-images')task=uploadImages(target.files);if(target.dataset.aiField&&target.dataset.aiType==='image'){if(target.value)state.edited[target.dataset.aiField]=JSON.parse(target.value);else delete state.edited[target.dataset.aiField];}if(target.dataset.aiCheck){target.checked?state.checked.add(target.dataset.aiCheck):state.checked.delete(target.dataset.aiCheck);redraw();}if(target.id==='ai-select-all'){shown().forEach(card=>target.checked?state.checked.add(card.id):state.checked.delete(card.id));redraw();}if(target.id==='ai-review-filter'){state.filter=target.value;redraw();}if(target.id==='ai-production-project'){if(state.busy){target.value=state.project?.id||'';return;}if(editorDirty()){target.value=state.project?.id||'';fail(new Error('请先保存当前替换，再切换制作草稿。'));return;}const id=target.value,mark=scope();state.token++;state.epoch++;mark.epoch=state.epoch;const choices=state.owner==='standalone'?state.projects:P.matchingProjects(state.owner,state.projects,state.assets);if(choices.some(project=>project.id===id))task=client.request(`/projects/${id}`).then(result=>{if(!live(mark))return;state.inputDirty=false;applyProject(result.project,{input:true});state.checked.clear();state.edited={};state.styleId=null;state.run=null;state.job=null;paint();});}if(task)task.catch(fail);});
 document.addEventListener('click',event=>{if(S.view!=='ai-making')return;const target=event.target.closest('[data-ai-action],[data-ai-choice]');if(!target||target.disabled)return;event.preventDefault();Promise.resolve().then(async()=>{if(target.dataset.aiChoice){if(state.busy)return;if(target.dataset.aiChoice!==state.styleId)requireSaved();if(target.dataset.aiChoice==='none'){if(current())await batch('reject',[current().id]);}else{const choice=asset(target.dataset.aiChoice),saved=current()?.style;state.styleId=choice?.id===saved?.asset_id&&choice?.revision===saved?.revision?null:target.dataset.aiChoice;state.edited={};$('.ai-inspector-scroll').innerHTML=editorHTML();}return;}switch(target.dataset.aiAction){case'video':$('#ai-video-file').click();break;case'audio':$('#ai-audio-file').click();break;case'transcript':useTranscript();break;case'generate':await generate();break;case'duplicate':if(state.project&&!state.busy){requireSaved();const mark=scope();setBusy(true);let result;try{result=await client.request(`/projects/${mark.id}/duplicate`,{});}finally{if(live(mark))setBusy(false);}if(!live(mark))break;state.token++;state.epoch++;state.projects.unshift(result.project);state.inputDirty=false;applyProject(result.project,{input:true});state.checked.clear();state.edited={};state.styleId=null;state.run=null;state.job=null;paint();setStatus('已建立独立制作副本，继续复用同一版本的样式与素材。');}break;case'refresh':requireSaved();state.inputDirty=false;state.edited={};state.styleId=null;await hydrate(true);break;case'select':selectCard(Number(target.dataset.aiIndex));break;case'save-time':await saveTiming();break;case'save-effect':await saveEffect();break;case'frame-back':seek(state.position-1/T.fps(source()));break;case'frame-forward':seek(state.position+1/T.fps(source()));break;case'images':$('#ai-shared-images').click();break;case'cases':await importCases();break;case'import-case':await importCase(target.dataset.aiCase);break;case'save-fields':await saveFields();break;case'discard-edits':if(!state.busy){state.edited={};state.styleId=null;redraw();setStatus('未保存替换已撤销，沿用服务器中的内容。');}break;case'save-batch':await saveFields(true);break;case'preview':await startJob('preview');break;case'preview-current':if(current())await startJob('preview',[current().id]);break;case'render':await startJob('render');break;case'approve':{const review=T.approval(state.project,selectedIds());if(!review.ready.length)throw new Error('所选片段尚无可确认的预览，请先补素材或保留口播。');await batch('approve',review.ready);if(review.blocked.length)setStatus(`已确认 ${review.ready.length} 段；${review.blocked.length} 段缺口或未通过预览，继续保留待审。`);break;}case'reject':await batch('reject');break;case'reset':await batch('reset');break;case'confirm':if(current())await batch(current().status==='approved'?'reset':'approve',[current().id]);break;case'export':exportPlan();break;case'cancel-run':if(state.run)await client.request(`/runs/${state.run.id}/cancel`,{});break;case'resume-run':await generate(state.run?.id);break;}}).catch(fail);});
 return{render};
})();
